<?php
declare(strict_types=1);
require_once __DIR__.'/store_helpers.php';
function render_error_page(int $code,string $title,string $heading,string $message,string $actionLabel='BACK TO HOME',?string $actionUrl=null,?string $reference=null): never {
    http_response_code($code);if(!headers_sent()){header('Cache-Control: no-store, max-age=0');header('X-Robots-Tag: noindex, nofollow');}
    $storeName='Online Store';try{$storeName=store_runtime_name();}catch(\Throwable){}
    $signedIn=!empty($_SESSION['user_id']);$home=function_exists('route_url')?route_url('index.php'):'/';$account=function_exists('route_url')?($signedIn?route_url('dashboard.php'):route_url('login.php')):'/';
    if($actionUrl===null)$actionUrl=match($code){419=>$account,503=>(string)($_SERVER['REQUEST_URI']??$home),default=>$home};
    if($actionLabel==='BACK TO HOME')$actionLabel=match($code){401=>'SIGN IN',403=>$signedIn?'BACK TO ACCOUNT':'BACK TO HOME',419=>'SIGN IN AGAIN',429=>'TRY AGAIN',503=>'TRY AGAIN',default=>'BACK TO HOME'};
    $context=match($code){400=>['BAD REQUEST','The request could not be understood. Check the information and try again.'],401=>['SIGN IN REQUIRED','Please sign in before opening this protected page.'],403=>['ACCESS RESTRICTED','Your account does not have permission to open this area.'],404=>['PAGE NOT FOUND','The page may have moved, been removed, or the address may be incorrect.'],405=>['METHOD NOT ALLOWED','This action cannot be completed using the current request method.'],409=>['REQUEST CONFLICT','The request conflicts with the current state of the resource. Refresh and try again.'],419=>['SESSION EXPIRED','Your security session timed out. Sign in again before repeating the action.'],422=>['CHECK YOUR DETAILS','Some submitted information could not be accepted. Review it and try again.'],429=>['TOO MANY REQUESTS','Too many attempts were received in a short period. Wait briefly and try again.'],500=>['SERVER ERROR','Something unexpected happened while processing the request.'],503=>['TEMPORARILY UNAVAILABLE','The store is temporarily unavailable while maintenance is in progress.'],default=>['REQUEST ERROR','The request could not be completed.']};
    $secondaryUrl=$code===419?$home:$account;$secondaryLabel=$code===419?'HOME':($signedIn?'MY ACCOUNT':'SIGN IN');?>
<!doctype html><html lang="<?=store_h(store_lang())?>" dir="<?=store_h(store_lang_dir())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f7f4ee"><title><?=store_h($title.' · '.$storeName)?></title><link rel="icon" type="image/svg+xml" href="<?=store_h(asset_url('assets/images/favicon-store.svg'))?>"><link rel="alternate icon" type="image/x-icon" href="<?=store_h(asset_url('favicon.ico'))?>"><link rel="apple-touch-icon" href="<?=store_h(asset_url('apple-touch-icon.png'))?>"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?=store_h(asset_url('assets/css/error.css'))?>"></head><body class="error-luxury-page"><header class="error-header"><a href="<?=store_h($home)?>" class="error-brand"><strong><?=store_h($storeName)?></strong><small><?=store_h(store_lang()==='ar'?'متجر إلكتروني':'ONLINE STORE')?></small></a></header><main class="error-main"><section class="error-card" aria-labelledby="error-title"><div class="error-number" aria-hidden="true"><?=store_h((string)$code)?></div><div class="error-copy"><span class="error-kicker"><?=store_h(store_t($context[0]))?></span><h1 id="error-title"><?=store_h(store_t($heading))?></h1><p class="error-message"><?=store_h(store_t($message))?></p><p class="error-context"><?=store_h(store_t($context[1]))?></p><?php if($reference):?><div class="error-reference"><span><?=store_h(store_t('REFERENCE ID'))?></span><strong><?=store_h($reference)?></strong></div><?php endif;?><div class="error-actions"><a class="error-primary" href="<?=store_h($actionUrl)?>"><?=store_h(store_t($actionLabel))?> <span>→</span></a><?php if($secondaryUrl!==$actionUrl):?><a class="error-secondary" href="<?=store_h($secondaryUrl)?>"><?=store_h(store_t($secondaryLabel))?></a><?php endif;?></div></div></section></main><footer class="error-footer"><span>© <?=date('Y')?> <?=store_h($storeName)?></span><span><?=store_h(store_lang()==='ar'?'تسوق بأمان':'SHOP SECURELY')?></span></footer></body></html><?php exit;}
